from src.billing.tax import invoice_tax, line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_uses_bankers_rounding():
    assert tax_for(25, Decimal("0.1")) == 2  # 2.5 -> 2
    assert tax_for(35, Decimal("0.1")) == 4  # 3.5 -> 4


def test_invoice_tax_rounds_per_line():
    lines = [
        {"quantity": 1, "unit_cents": 15},
        {"quantity": 1, "unit_cents": 15},
    ]
    # Per line: 1.5 -> 2 each, total 4 (rounding the 3.0 total would give 3).
    assert invoice_tax(lines, Decimal("0.1")) == 4


def test_invoice_tax_float_rate():
    assert invoice_tax([{"quantity": 2, "unit_cents": 1000}], 0.0825) == 165


def test_invoice_tax_empty():
    assert invoice_tax([], Decimal("0.1")) == 0"
}

